147	// 当前值不是整数：本条命令不改变键值表，应用停在该条目之前，此前结果保留。
148	func TestKVIncrBadCurrentValue(t *testing.T) {
149		out := runKV(t, InitialState{CurrentTerm: 1},
150			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 3,
151				Entries: []LogEntry{
152					entry(1, 1, "set k=hello"), // 非整数当前值
153					entry(2, 1, "set ok=1"),
154					entry(3, 1, "incr k=1"),
155				}},
156		)
157		if got := appliedIndexOf(t, out.Results[0]); got != 2 {
158			t.Fatalf("appliedIndex = %d, want 2 (stuck before failing entry)", got)
159		}
160		err := out.Results[0].ApplyError
161		if err == nil || err.Index != 3 || err.Reason != ApplyReasonIncrBadCurrent {
162			t.Fatalf("applyError = %+v, want index 3 bad current value", err)
163		}
164		kv := finalKVOf(t, out)
165		want := map[string]string{"k": "hello", "ok": "1"} // k 保持原值
166		if !reflect.DeepEqual(kv, want) {
167			t.Fatalf("finalKV = %v, want %v (failing incr must not change the table)", kv, want)
168		}
169		if out.FinalApplyError == nil || out.FinalApplyError.Index != 3 ||
170			out.FinalApplyError.Reason != ApplyReasonIncrBadCurrent {
171			t.Fatalf("finalApplyError = %+v, want index 3 bad current value", out.FinalApplyError)
172		}
173	}
174	
175	// 增量非法：含空增量、正号、小数、超范围等，应用停在出错条目前。
176	func TestKVIncrBadDeltaStopsApplication(t *testing.T) {
177		out := runKV(t, InitialState{CurrentTerm: 1},
178			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 3,
179				Entries: []LogEntry{
180					entry(1, 1, "incr k=5"),
181					entry(2, 1, "incr k=1.5"), // 小数增量非法
182					entry(3, 1, "incr k=100"), // 出错之后不再应用
183				}},
184		)
185		if got := appliedIndexOf(t, out.Results[0]); got != 1 {
186			t.Fatalf("appliedIndex = %d, want 1", got)
187		}
188		err := out.Results[0].ApplyError
189		if err == nil || err.Index != 2 || err.Reason != ApplyReasonIncrBadDelta {
190			t.Fatalf("applyError = %+v, want index 2 bad delta", err)
191		}
192		kv := finalKVOf(t, out)
193		if !reflect.DeepEqual(kv, map[string]string{"k": "5"}) {
194			t.Fatalf("finalKV = %v, want only k=5", kv)
195		}
196	}
