198	// 相加溢出：当前值与增量各自合法，但和超出 int64 范围。
199	func TestKVIncrOverflow(t *testing.T) {
200		max := strconv.FormatInt(math.MaxInt64, 10)
201		cases := []struct {
202			name     string
203			commands []string
204		}{
205			{"positive overflow", []string{"set k=" + max, "incr k=1"}},
206			{"negative overflow", []string{"set k=" + strconv.FormatInt(math.MinInt64, 10), "incr k=-1"}},
207			{"two incr overflow", []string{"incr k=" + max, "incr k=" + max}},
208		}
209		for _, tc := range cases {
210			t.Run(tc.name, func(t *testing.T) {
211				entries := make([]LogEntry, len(tc.commands))
212				for i, command := range tc.commands {
213					entries[i] = entry(i+1, 1, command)
214				}
215				out := runKV(t, InitialState{CurrentTerm: 1},
216					AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0,
217						LeaderCommit: len(entries), Entries: entries},
218				)
219				if got := appliedIndexOf(t, out.Results[0]); got != len(entries)-1 {
220					t.Fatalf("appliedIndex = %d, want %d", got, len(entries)-1)
221				}
222				err := out.Results[0].ApplyError
223				if err == nil || err.Index != len(entries) || err.Reason != ApplyReasonIncrOverflow {
224					t.Fatalf("applyError = %+v, want index %d overflow", err, len(entries))
225				}
226			})
227		}
228	}
229	
230	// 三类 incr 失败的原因必须能互相区分。
231	func TestKVIncrErrorReasonsAreDistinct(t *testing.T) {
232		reasons := []string{ApplyReasonIncrBadCurrent, ApplyReasonIncrBadDelta, ApplyReasonIncrOverflow}
233		seen := map[string]bool{}
234		for _, reason := range reasons {
235			if seen[reason] {
236				t.Fatalf("duplicate incr error reason %q", reason)
237			}
238			seen[reason] = true
239		}
240	}
241	
242	// 未提交的 incr 不能提前改值或暴露数值错误；重复复制与心跳不重复累加。
243	func TestKVIncrCommitBoundaries(t *testing.T) {
244		out := runKV(t, InitialState{CurrentTerm: 1},
245			// 追加两条 incr 但都不提交：键值表仍为空，非法增量也不暴露。
246			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 0,
247				Entries: []LogEntry{entry(1, 1, "incr k=5"), entry(2, 1, "incr k=oops")}},
248			// 重复复制同一条日志（完全相同，保留），提交位置不变：不累加。
249			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 0,
250				Entries: []LogEntry{entry(1, 1, "incr k=5"), entry(2, 1, "incr k=oops")}},
251			// 心跳提交到 1：只累加一次。
252			AppendRequest{Term: 1, PrevLogIndex: 2, PrevLogTerm: 1, LeaderCommit: 1},
253			// 提交位置未前进的心跳：不重复累加。
254			AppendRequest{Term: 1, PrevLogIndex: 2, PrevLogTerm: 1, LeaderCommit: 1},
255			// 提交到 2：非法增量此时才报错，应用停在 1。
256			AppendRequest{Term: 1, PrevLogIndex: 2, PrevLogTerm: 1, LeaderCommit: 2},
257		)
258		wantApplied := []int{0, 0, 1, 1, 1}
259		for i, result := range out.Results {
260			if !result.Accepted {
261				t.Fatalf("result %d rejected: %s", i, result.Reason)
262			}
263			if got := appliedIndexOf(t, result); got != wantApplied[i] {
264				t.Fatalf("result %d appliedIndex = %d, want %d", i, got, wantApplied[i])
265			}
266		}
267		for i := 0; i < 4; i++ {
268			if out.Results[i].ApplyError != nil {
269				t.Fatalf("result %d unexpected apply error: %+v", i, out.Results[i].ApplyError)
270			}
271		}
272		last := out.Results[4]
273		if last.ApplyError == nil || last.ApplyError.Index != 2 ||
274			last.ApplyError.Reason != ApplyReasonIncrBadDelta {
275			t.Fatalf("result 4 applyError = %+v, want index 2 bad delta", last.ApplyError)
276		}
277		// incr k=5 恰好应用一次。
278		kv := finalKVOf(t, out)
279		if !reflect.DeepEqual(kv, map[string]string{"k": "5"}) {
280			t.Fatalf("finalKV = %v, want k=5 (applied exactly once)", kv)
281		}
282		if *out.FinalAppliedIndex != 1 {
283			t.Fatalf("finalAppliedIndex = %d, want 1", *out.FinalAppliedIndex)
284		}
285	}
286	
287	// 初始已提交前缀中的 incr 照常生效。
288	func TestKVIncrInitialCommittedPrefix(t *testing.T) {
289		initial := InitialState{CurrentTerm: 2, CommittedIndex: 3, Log: []LogEntry{
290			entry(1, 1, "incr k=10"),
291			entry(2, 2, "incr k=-3"),
292			entry(3, 2, "set other=x"),
293		}}
294		out := runKV(t, initial)
295		kv := finalKVOf(t, out)
296		want := map[string]string{"k": "7", "other": "x"}
297		if !reflect.DeepEqual(kv, want) {
298			t.Fatalf("finalKV = %v, want %v", kv, want)
299		}
300		if *out.FinalAppliedIndex != 3 {
301			t.Fatalf("finalAppliedIndex = %d, want 3", *out.FinalAppliedIndex)
302		}
303	}
304	
305	// incr 失败后应用停住：后续请求复制与提交照常推进，但不再应用任何条目。
306	func TestKVIncrErrorStopsLaterApplication(t *testing.T) {
307		out := runKV(t, InitialState{CurrentTerm: 1},
308			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 2,
309				Entries: []LogEntry{entry(1, 1, "incr k=1"), entry(2, 1, "incr k=abc")}},
310			AppendRequest{Term: 2, PrevLogIndex: 2, PrevLogTerm: 1, LeaderCommit: 3,
311				Entries: []LogEntry{entry(3, 2, "incr k=100")}},
312		)
313		if !out.Results[1].Accepted || out.Results[1].CommittedIndex != 3 {
314			t.Fatalf("replication must keep advancing: %+v", out.Results[1])
315		}
316		for i, result := range out.Results {
317			if got := appliedIndexOf(t, result); got != 1 {
318				t.Fatalf("result %d appliedIndex = %d, want 1 (stuck)", i, got)
319			}
320			if result.ApplyError == nil || result.ApplyError.Index != 2 {
321				t.Fatalf("result %d applyError = %+v, want index 2", i, result.ApplyError)
322			}
323		}
324		kv := finalKVOf(t, out)
325		if !reflect.DeepEqual(kv, map[string]string{"k": "1"}) {
326			t.Fatalf("finalKV = %v, want only k=1", kv)
327		}
328		if out.FinalTerm != 2 || out.FinalCommittedIndex != 3 {
329			t.Fatalf("final state = term %d ci %d, want term 2 ci 3", out.FinalTerm, out.FinalCommittedIndex)
330		}
331	}
332	
333	// applyKV 省略或为 false 时，incr 只是普通日志字符串，不增加应用字段。
334	func TestKVIncrDisabledStaysPlainString(t *testing.T) {
335		initial := InitialState{CurrentTerm: 1, CommittedIndex: 1, Log: []LogEntry{
336			entry(1, 1, "incr k=1"),
337		}}
338		out, err := Replicate(initial, []AppendRequest{
339			{Term: 1, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 2,
340				Entries: []LogEntry{entry(2, 1, "incr k=oops")}},
341		})
342		if err != nil {
343			t.Fatal(err)
344		}
345		if out.FinalCommittedIndex != 2 || len(out.FinalLog) != 2 {
346			t.Fatalf("replication state wrong: %+v", out)
347		}
348		encoded, err := json.Marshal(out)
349		if err != nil {
350			t.Fatal(err)
351		}
352		body := string(encoded)
353		for _, field := range []string{"appliedIndex", "applyError", "finalAppliedIndex", "finalKV", "finalApplyError"} {
354			if strings.Contains(body, field) {
355				t.Fatalf("applyKV disabled: output must not contain %q: %s", field, body)
356			}
357		}
358		if !strings.Contains(body, "incr k=oops") {
359			t.Fatalf("incr command must stay in the log verbatim: %s", body)
360		}
361	}
